function renderServices(){const choices=services.filter(s=>s.active).map(s=>`<option value="${esc(s.id)}">${esc(s.name)} · ${money(s.price)}</option>`).join('');$('#service-select').innerHTML=choices;$('#form-service').innerHTML=choices;$('#service-select').value=selectedService;$('#form-service').value=selectedService;updateFee();}
function updateFee(){const s=selected();$('#total').textContent=s?num(s.price):'—';$('.booking-body .fee-line strong').innerHTML=s?`${money(s.price)}<small>${num(s.duration_minutes)} دقيقة</small>`:'لا توجد خدمات متاحة';$('#emergency-note').hidden=s?.category!=='emergency';for(const input of $('#booking-form').querySelectorAll('[name=payment]'))input.disabled=input.value==='instapay'?!clinic.instapay:input.value==='wallet'?!clinic.wallet:false;if($('#booking-form').querySelector('[name=payment]:checked')?.disabled)$('#booking-form').elements.payment.value='cash';const method=$('#booking-form').elements.payment.value;$('#payment-note').hidden=method==='cash';$('#payment-note').textContent=method==='instapay'?('التحويل إلى: '+clinic.instapay+' — يراجعه الاستقبال قبل تأكيد الاستلام.'):('رقم المحفظة: '+clinic.wallet+' — يراجعه الاستقبال قبل تأكيد الاستلام.');}
async function loadAvailability(){
 const revision=++loadRevision;$('.booking-card').classList.add('loading');$('#slots-count').textContent='جارٍ تحميل المواعيد…';available=[];selectedTime=selectedTime||'';$('#continue-booking').disabled=true;
 try{if(!selected()){renderSlots();return;}if(live){const loaded=await api.rpc('available_slots',{p_clinic:clinic.id,p_service:selectedService,p_date:selectedDate});if(revision!==loadRevision)return;available=loaded;}else if(demo){
 available=D.availableSlots(clinic,selected(),selectedDate,bookings);
 }else available=[];if(!available.includes(selectedTime))selectedTime=available[0]||'';renderSlots();}catch(e){if(revision===loadRevision){available=[];selectedTime='';renderSlots();$('#slots').innerHTML='<p class="slot-empty error">تعذر تحميل المواعيد. غيّر التاريخ لإعادة المحاولة.</p>';}throw e;}finally{if(revision===loadRevision)$('.booking-card').classList.remove('loading');}
}
function renderSlots(){const ds=[0,1,2].map(n=>({date:D.cairoDate(new Date(Date.now()+n*86400000)),label:['اليوم','غدًا','بعد غد'][n]}));$('#days').innerHTML=ds.map(d=>`<button data-date="${d.date}" class="${d.date===selectedDate?'selected':''}" aria-pressed="${d.date===selectedDate}"><strong>${d.label}</strong><span>${d.date}</span></button>`).join('');$('#slots').innerHTML=available.map(t=>`<button data-time="${t}" class="${t===selectedTime?'selected':''}" aria-label="وقت الوصول ${t}" aria-pressed="${t===selectedTime}">${t}</button>`).join('')||'<p class="slot-empty">لا توجد مواعيد متاحة في اليوم ده.<br>اختار يومًا آخر.</p>';$('#slots-count').textContent=available.length?num(available.length)+' موعد متاح':'اختار يومًا آخر';$('#continue-booking').disabled=!selectedTime||!available.length;$('#selected-slot').textContent=new Intl.DateTimeFormat('ar-EG',{timeZone:'Africa/Cairo',weekday:'short',month:'short',day:'numeric'}).format(new Date(selectedDate+'T12:00:00Z'))+' · '+(selectedTime||'لا يوجد موعد');$('#booking-date').value=selectedDate;}
function etaFor(b){return live?b.eta:demo?D.estimates(bookings,{paused:clinic.paused,buffer:clinic.buffer_minutes})[b.id]:null;}
