 document.querySelectorAll('[data-doctor]').forEach(el=>el.hidden=role!=='doctor');$('#view-toggle').dataset.action=view==='admin'?'patient':'admin';$('#view-toggle').innerHTML=icon('dashboard')+(view==='admin'?'صفحة المريض':live?'دخول العيادة':demo?'تجربة لوحة العيادة':'إعداد الربط');
 const today=bookings.filter(b=>D.cairoDate(new Date(b.scheduled_at))===D.cairoDate()&&b.status!=='cancelled'),waiting=today.filter(b=>b.status==='waiting').sort((a,b)=>b.priority-a.priority||a.scheduled_at.localeCompare(b.scheduled_at)),current=bookings.find(b=>b.status==='inside');
 $('#live-number').textContent=live&&!staff()?'تابع موعدك بأمان':current?'كشف جارٍ · تابع حجزك':'لا يوجد كشف حالي';
 $('#stats').innerHTML=[['حجوزات اليوم',today.length,'calendar','كشف ومتابعة'],['في الانتظار',waiting.length,'clock','حسب الأولوية والوصول'],['تم الكشف',today.filter(b=>b.status==='done').length,'check','زيارات مكتملة'],['المحصّل اليوم',today.filter(b=>b.paid).reduce((n,b)=>n+Number(b.price),0),'wallet','جنيه مصري']].map(([label,value,i,note])=>`<article><div><span>${label}</span>${icon(i)}</div><strong>${num(value)}</strong><small>${note}</small></article>`).join('');
 const q=$('#query').value.trim().toLowerCase();const filtered=bookings.filter(b=>(b.name+' '+b.phone).toLowerCase().includes(q)&&(!adminDate||D.cairoDate(new Date(b.scheduled_at))===adminDate)&&(stateFilter==='all'||stateFilter==='unpaid'&&!b.paid&&b.status!=='cancelled'||b.status===stateFilter)&&(tab!=='payments'||b.status!=='cancelled')).sort((a,b)=>a.scheduled_at.localeCompare(b.scheduled_at));$('#results-count').textContent=num(filtered.length)+' حجز';$('#role-label').textContent=role==='doctor'?'مساحة الدكتور':role==='reception'?'مساحة الاستقبال':'فريق العيادة';
 $('#table-title').textContent=tab==='appointments'?'الحجوزات والملفات':'متابعة التحصيل';
