 $('#current').innerHTML=`<span>داخل غرفة الكشف</span><strong>${current?icon('activity'):'—'}</strong><h3>${current?esc(current.name):'لا يوجد مريض حاليًا'}</h3><small>${current?esc(current.service_name):'سجّل وصول المريض قبل تشغيل التالي'}</small>`;
