function showView(v){if(v==='admin'&&!staff()){if(live){$('#login-dialog').showModal();return;}if(demo)role=$('#demo-role').value;else ensureDataMode();}view=v;$('#patient').hidden=v!=='patient';$('#admin').hidden=v!=='admin';$('.skip-link').href=v==='admin'?'#admin':'#patient';document.querySelectorAll('.top-nav button').forEach(b=>b.classList.toggle('active',v==='patient'&&b.dataset.action==='patient'));render();window.scrollTo({top:0,behavior:'smooth'});}
function setTab(value){tab=value;document.querySelectorAll('[data-tab]').forEach(t=>{t.classList.toggle('active',t.dataset.tab===tab);t.setAttribute('aria-selected',String(t.dataset.tab===tab));t.tabIndex=t.dataset.tab===tab?0:-1;});$('#table-panel').setAttribute('aria-labelledby','tab-'+tab);render();}
function selectWorkspace(screen='workspace'){workspace=screen;$('#extra-panel').hidden=['workspace','appointments','payments'].includes(screen);$('.admin-grid').hidden=!$('#extra-panel').hidden;$('#stats').hidden=!$('#extra-panel').hidden;document.querySelectorAll('.admin-sidebar nav button').forEach(b=>{b.classList.toggle('active',b.dataset.action===screen);if(b.dataset.action===screen)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});}
function patientSearchKey(value=''){return String(value??'').normalize('NFKC').replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).toLocaleLowerCase('ar-EG').trim();}
function patientPhoneKey(value=''){let digits=patientSearchKey(value).replace(/\D/g,'');if(digits.startsWith('20')&&digits.length===12)digits='0'+digits.slice(2);return digits;}
function renderPatientDirectory(query=''){const needle=patientSearchKey(query),digits=patientPhoneKey(query),found=patients.filter(p=>patientSearchKey(p.name).includes(needle)||(digits&&patientPhoneKey(p.phone).includes(digits)));const empty=patients.length?'<p class="empty">لا توجد نتائج مطابقة. جرّب جزءًا من الاسم أو رقم الموبايل.</p>':'<p class="empty">لا توجد ملفات مرضى محفوظة في العيادة الحالية. إذا كنت ترى حجوزات المرضى، حدّث القائمة وتأكد من حساب العيادة.</p>';const count=$('#patient-count');if(count)count.textContent=num(patients.length)+' ملف';$('#patient-directory').innerHTML=found.map(p=>`<div class="service-row"><strong>${esc(p.name)}<small>ملف مريض</small></strong><span dir="ltr">${esc(p.phone)}</span><button class="inline-button" data-record="${p.id}">فتح الملف ${icon('arrow')}</button></div>`).join('')||empty;}
async function showRecords(){requireRole('doctor');await loadPatients();selectWorkspace('records');$('#extra-panel').innerHTML='<div class="panel-heading"><h2>ملفات المرضى</h2><span id="patient-count" class="status done">'+num(patients.length)+' ملف</span><button class="inline-button" data-action="refresh-patients">تحديث القائمة</button></div><p class="muted">التاريخ المرضي والزيارات والتشخيص والروشتة في مكان واحد.</p><input class="panel-search" id="patient-search" placeholder="ابحث باسم المريض أو الموبايل" aria-label="بحث ملفات المرضى"><div id="patient-directory"></div>';renderPatientDirectory();}
async function refresh(){if(!live||!api?.session||refreshing)return;refreshing=true;const generation=api.generation;try{const data=await api.rpc('clinic_snapshot',{p_clinic:clinic.id});if(generation!==api.generation||!api.session)return;if(role!==data.role){historyBookings=[];historyLoaded=false;}if(role==='doctor'&&data.role!=='doctor'){selectWorkspace();medical={};encounters=[];activeRecord=null;lastPrescription=null;$('#record-dialog').close();$('#record-history').innerHTML='';$('#record-form').reset();$('#print-area').innerHTML='';$('#extra-panel').innerHTML='';$('#extra-panel').hidden=true;}role=data.role;bookings=[...data.bookings,...historyBookings];notifications=data.notifications;const profile=await api.rpc('resolve_clinic',{p_host:location.hostname,p_slug:config.clinicSlug||new URLSearchParams(location.search).get('clinic')||''});if(generation!==api.generation||!api.session)return;clinic=profile.clinic;services=staff()?await api.request('/rest/v1/services?clinic_id=eq.'+clinic.id+'&select=*'):profile.services;if(!selected())selectedService=services.find(s=>s.active)?.id;renderBrand();renderServices();await loadAvailability();render();if(workspace==='records')await loadPatients();if(!staff()&&view==='admin')showView('patient');}finally{refreshing=false;}}
function subscribe(){api.subscribe(clinic.id,()=>refresh().then(()=>historyLoaded?loadBookingHistory(true):null).catch(e=>notify(e.message)),s=>{if($('#connection'))$('#connection').textContent=({connected:'تحديث مباشر متصل',reconnecting:'إعادة اتصال…',expired:'انتهت الجلسة؛ سجّل الدخول',error:'التحديث المباشر غير متاح؛ جارٍ التحديث الدوري'})[s]||s;});}
async function loadBookingHistory(force=false){ensureDataMode();if(!live||(!force&&historyLoaded))return;if(historyLoading)return historyLoading;const generation=api.generation;historyLoading=(async()=>{let after=null,afterId=null,all=[];for(;;){const page=await api.rpc('clinic_booking_history',{p_clinic:clinic.id,p_after:after,p_after_id:afterId,p_limit:500});if(generation!==api.generation||!api.session)return;if(!Array.isArray(page))throw Error('تعذر تحميل سجل الحجوزات.');all.push(...page);if(page.length<500)break;const last=page[page.length-1];after=last.scheduled_at;afterId=last.id;}if(generation!==api.generation||!api.session)return;historyBookings=all;historyLoaded=true;bookings=[...new Map([...bookings,...all].map(b=>[b.id,b])).values()];render();})();try{return await historyLoading;}finally{historyLoading=null;}}
async function loadPatients(){if(live){const pageSize=1000,all=[];for(let offset=0;;offset+=pageSize){const page=await api.request('/rest/v1/patients?clinic_id=eq.'+encodeURIComponent(clinic.id)+'&select=id,name,phone&order=name&limit='+pageSize+'&offset='+offset);all.push(...page);if(page.length<pageSize)break;}patients=all;}else if(demo)patients=[...new Map(bookings.map(b=>[b.patient_id,{id:b.patient_id,name:b.name,phone:b.phone}])).values()];else patients=[];if(workspace==='records'&&$('#patient-directory'))renderPatientDirectory($('#patient-search')?.value||'');}
async function openBooking(){ensureDataMode();if(staff()){await loadPatients();$('#existing-patient').innerHTML='<option value="">مريض جديد</option>'+patients.map(p=>'<option value="'+p.id+'">'+esc(p.name)+' · '+esc(p.phone)+'</option>').join('');}$('#existing-patient-field').hidden=!staff();if(!selectedTime||!selected())throw Error('اختار خدمة وموعدًا متاحًا أولًا.');$('#booking-form').hidden=false;$('#booking-success').hidden=true;$('#booking-error').hidden=true;$('#booking-title').textContent='خطوة واحدة وموعدك جاهز';$('#booking-dialog .dialog-eyebrow').hidden=false;renderSlots();updateFee();$('#auth-hint').textContent=live&&!api.session?'بعد التأكيد سيُطلب رمز يُرسل إلى موبايلك.':'';$('#booking-dialog').showModal();}
async function saveBooking(){ensureDataMode();const f=$('#booking-form').elements,name=f.name.value.trim(),phone=D.normalizePhone(f.phone.value),s=selected();if(name.length<3||!/^01[0125]\d{8}$/.test(phone))throw Error('اكتب اسمًا صحيحًا ورقم موبايل مصري من ١١ رقمًا.');if(!s||!available.includes(selectedTime))throw Error('اختار موعدًا متاحًا.');if(live&&!api.session){$('#booking-dialog').close();$('#otp-form').elements.phone.value=phone;$('#otp-dialog').showModal();return;}
 let b;if(live){b=await api.rpc('book_appointment',{p_clinic:clinic.id,p_service:s.id,p_name:name,p_phone:phone,p_date:selectedDate,p_time:selectedTime,p_payment:f.payment.value,p_travel:Number(f.travel.value),p_consent:f.consent.checked,p_request:requestKey,p_patient:staff()?($('#existing-patient').value||null):null});await refresh();b=bookings.find(x=>x.id===b.id)||{...b,name,phone};}else{const [h,m]=selectedTime.split(':').map(Number);b={id:crypto.randomUUID(),clinic_id:clinic.id,patient_id:staff()?($('#existing-patient').value||crypto.randomUUID()):crypto.randomUUID(),name,phone,service_id:s.id,service_name:s.name,price:+s.price,duration_minutes:+s.duration_minutes,priority:+s.priority,category:s.category,status:'waiting',arrived:false,triage:s.category==='emergency'?'pending':'approved',paid:false,payment_method:f.payment.value,travel_minutes:Number(f.travel.value),notification_consent:f.consent.checked,scheduled_at:D.cairoInstant(selectedDate,selectedTime),demo_date:selectedDate,demo_minute:h*60+m};bookings.push(b);}
 requestKey=crypto.randomUUID();trackedId=b.id;$('#booking-form').hidden=true;$('#booking-success').hidden=false;$('#booking-dialog .dialog-eyebrow').hidden=true;$('#booking-title').textContent='تم تسجيل الحجز';$('#booking-success').innerHTML=`${icon('check')}<h3>${esc(b.name)}</h3><p>تم حجز ${esc(b.service_name)} يوم ${selectedDate} الساعة ${selectedTime}.</p><p>${b.triage==='pending'?'طلب الطوارئ بانتظار مراجعة الدكتور.':''} ${b.paid?'تم الاستلام':'الدفع بانتظار تأكيد الاستقبال.'}</p><p>تابع حجزك بعد تأكيد رقم الموبايل؛ لا تحتاج إلى رقم حجز.</p><button class="primary full" data-action="track-last">متابعة حجوزاتي بالموبايل</button>`;notify('تم تسجيل الحجز.');await loadAvailability();render();}
function renderTracking(){const list=bookings.filter(b=>demo||role==='patient').sort((a,b)=>{const active=x=>['waiting','inside'].includes(x.status)?0:1;return active(a)-active(b)||Date.parse(a.scheduled_at)-Date.parse(b.scheduled_at);});if(!list.length){$('#track-result').innerHTML='<p class="error">لا توجد حجوزات مرتبطة برقم الموبايل الذي تم تأكيده.</p>';return;}if(!trackedId||!list.some(b=>b.id===trackedId))trackedId=list[0].id;$('#track-result').innerHTML=list.map(b=>{const eta=etaFor(b);return `<article class="track-result"><div class="track-card-heading"><span class="status ${b.status}">${status(b)}</span><button type="button" class="text-button" data-track-booking="${esc(b.id)}" aria-pressed="${String(b.id===trackedId)}">${b.id===trackedId?'المتابعة الحالية':'عرض التفاصيل'}</button></div><h3>${esc(b.name)}</h3><p>${esc(b.service_name)} · ${time(b.scheduled_at)} · ${D.cairoDate(new Date(b.scheduled_at))}</p><div class="eta-box">${b.triage==='pending'?'طلب الطوارئ بانتظار مراجعة الدكتور.':clinic.paused?'الدور متوقف مؤقتًا. انتظر تحديث العيادة.':b.status==='waiting'&&eta?.minutes!=null?`الدخول المتوقع خلال<strong>${D.formatDuration(eta.low)} – ${D.formatDuration(eta.high)}</strong>${eta.leaveIn===0?'وقت التحرك الآن حسب مدة الطريق التي أدخلتها.':'اتحرك بعد حوالي '+D.formatDuration(eta.leaveIn)+'.'}`:b.status==='inside'?'حان دورك. توجّه إلى الاستقبال.':b.status==='done'?'تم الكشف. نتمنا لك دوام الصحة.':'لا يوجد انتظار نشط لهذا الحجز.'}<small>التقدير يتحدث تلقائيًا ويتأثر بمدة الكشف والأولوية. مدة الطريق أدخلتها أنت وليست قراءة مباشرة لحركة المرور.</small></div><a class="primary full" style="margin-top:12px" target="_blank" rel="noopener" href="${esc(D.mapsUrl(clinic))}">الاتجاهات على Google Maps</a><p>${b.paid?'تم تأكيد الاستلام':'الدفع بانتظار تأكيد الاستقبال'}</p></article>`;}).join('');}
async function staffAction(action,id){ensureDataMode();requireRole('staff');const current=bookings.find(b=>b.status==='inside');if(live){await api.rpc('staff_action',{p_clinic:clinic.id,p_action:action,p_appointment:id||null,p_expected:current?.id||null});await refresh();if(historyLoaded)try{await loadBookingHistory(true);}catch{notify('تم التحديث، لكن تعذر تحديث سجل الحجوزات.');}}else{const b=bookings.find(x=>x.id===id);if(action==='pause'||action==='resume')clinic.paused=action==='pause';else if(action==='next'){if(clinic.paused)throw Error('الدور متوقف.');const next=bookings.filter(b=>b.status==='waiting'&&b.arrived&&b.triage==='approved'&&D.cairoDate(new Date(b.scheduled_at))===D.cairoDate()&&Date.parse(b.scheduled_at)<=Date.now()+15*60000).sort((a,b)=>b.priority-a.priority||a.scheduled_at.localeCompare(b.scheduled_at))[0];if(current){current.status='done';current.finished_at=new Date().toISOString();}if(next){next.status='inside';next.started_at=new Date().toISOString();}}else if(!b)throw Error('الحجز غير موجود.');else if(action==='approve'){requireRole('doctor');b.triage='approved';}else if(action==='arrive')b.arrived=true;else if(action==='pay'){if(b.status==='cancelled')throw Error('الحجز ملغي.');b.paid=true;}else if(action==='cancel'){if(b.paid||b.status!=='waiting')throw Error('الحجز غير قابل للإلغاء.');b.status='cancelled';}render();}notify('تم تحديث العيادة.');await loadAvailability();}
function showServices(){ensureDataMode();requireRole('doctor');selectWorkspace('services');$('#extra-panel').innerHTML='<div class="panel-heading"><h2>الخدمات والأسعار</h2><button class="primary" data-action="new-service">+ إضافة خدمة</button></div><p class="muted">حدد السعر والمدة والأولوية لكل زيارة. الحجوزات السابقة تحتفظ بتفاصيلها.</p>'+services.map(s=>`<div class="service-row"><strong>${esc(s.name)}<small>${s.active?'متاحة للحجز':'موقوفة'}</small></strong><span>${money(s.price)}</span><span>${num(s.duration_minutes)} دقيقة · أولوية ${num(s.priority)}</span><button class="inline-button" data-edit-service="${s.id}">تعديل الخدمة</button></div>`).join('');}
function editService(id){requireRole('doctor');editingService=id||null;const s=services.find(s=>s.id===id)||{name:'',category:'normal',price:350,duration_minutes:20,priority:0,active:true};const f=$('#service-form').elements;for(const k of ['name','category','price','duration_minutes','priority','active'])f[k].value=String(s[k]);$('#service-dialog').showModal();}
async function openRecord(id){ensureDataMode();requireRole('doctor');activeRecord=bookings.find(b=>b.id===id);if(!activeRecord){const p=patients.find(p=>p.id===id);if(!p)throw Error('الملف غير موجود.');const last=live?await api.request('/rest/v1/appointments?clinic_id=eq.'+clinic.id+'&patient_id=eq.'+p.id+'&select=*&order=scheduled_at.desc&limit=1'):bookings.filter(b=>b.patient_id===p.id);activeRecord={...(last[0]||{id:null,status:'none'}),patient_id:p.id,name:p.name,phone:p.phone};}let record,visits;if(live){[record,visits]=await Promise.all([api.request('/rest/v1/medical_records?clinic_id=eq.'+clinic.id+'&patient_id=eq.'+activeRecord.patient_id+'&select=*'),api.request('/rest/v1/encounters?clinic_id=eq.'+clinic.id+'&patient_id=eq.'+activeRecord.patient_id+'&select=*&order=created_at.desc')]);record=record[0];}else{record=medical[activeRecord.patient_id];visits=encounters.filter(v=>v.patient_id===activeRecord.patient_id);}
 $('#record-patient').textContent=activeRecord.name+' · '+activeRecord.phone;const f=$('#record-form').elements;f.allergies.value=record?.allergies||'';f.history.value=record?.history||'';f.diagnosis.value='';f.notes.value='';$('#medications').innerHTML='';$('#record-form').hidden=!['inside','done'].includes(activeRecord.status);$('#record-history').innerHTML=visits.map(v=>`<article class="patient-record"><strong>${esc(v.diagnosis)}</strong><p>${esc(v.notes)}</p><small>${new Date(v.created_at).toLocaleDateString('ar-EG')}</small><button class="inline-button" data-print-visit="${v.id}">عرض / طباعة الروشتة</button></article>`).join('')||'<p class="muted">لا توجد زيارات مسجلة. إضافة الكشف متاحة أثناء الزيارة أو بعد إنهائها.</p>';if(live)encounters=visits;$('#record-dialog').showModal();}
function addMedication(){requireRole('doctor');$('#medications').insertAdjacentHTML('beforeend','<div class="medication-row"><input name="med-name" placeholder="اسم الدواء" aria-label="اسم الدواء" required maxlength="120"><input name="med-dose" placeholder="الجرعة" aria-label="الجرعة" required maxlength="200"><input name="med-frequency" placeholder="التكرار" aria-label="التكرار" required maxlength="200"><input name="med-duration" placeholder="المدة" aria-label="المدة" required maxlength="200"><button type="button" data-remove-med aria-label="حذف الدواء">×</button></div>');}
function printVisit(id){requireRole('doctor');const v=encounters.find(x=>x.id===id)||lastPrescription;if(!v)throw Error('الروشتة غير موجودة.');$('#print-area').innerHTML=`<h1>${esc(clinic.name)}</h1><p>${esc(clinic.specialty)} · ${esc(clinic.address)}</p><hr><h2>روشتة طبية</h2><p>المريض: ${esc(activeRecord.name)} · ${new Date(v.created_at).toLocaleDateString('ar-EG')}</p><p>التشخيص: ${esc(v.diagnosis)}</p><table><thead><tr><th>الدواء</th><th>الجرعة</th><th>التكرار</th><th>المدة</th></tr></thead><tbody>${v.medications.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.dose)}</td><td>${esc(m.frequency)}</td><td>${esc(m.duration)}</td></tr>`).join('')}</tbody></table><p>${esc(v.notes)}</p><p>توقيع الدكتور: __________________</p>`;window.print();}
async function execute(fn){if(pending)return;pending=true;const form=document.querySelector('dialog[open] form:not([hidden])'),error=form?.querySelector('[role=alert]');if(error)error.hidden=true;const buttons=[...document.querySelectorAll('dialog[open] button[type=submit],dialog[open] form button:not([data-close]),#service-select,#form-service,#booking-date,#demo-role,#existing-patient,[data-date],[data-time],[data-action=next],[data-staff],[data-choose-service]')].filter(b=>!b.disabled);buttons.forEach(b=>{b.disabled=true;b.dataset.busy='true';});document.body.setAttribute('aria-busy','true');try{await fn();}catch(e){const message=e.message||'تعذر إتمام العملية.';if(error&&form.isConnected){error.textContent=message;error.hidden=false;error.scrollIntoView({block:'nearest'});}else notify(message);}finally{pending=false;buttons.forEach(b=>{if(b.isConnected){b.disabled=false;delete b.dataset.busy;}});document.body.removeAttribute('aria-busy');render();}}

initializeUI();if(demo)seed();
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(!el.matches('[data-close],[data-remove-med],[data-track-booking],[data-action],[data-date],[data-time],[data-tab],[data-staff],[data-edit-service],[data-record],[data-print-visit],[data-choose-service]'))return;if(el.hasAttribute('data-close')){el.closest('dialog').close();return;}if(el.hasAttribute('data-remove-med')){el.closest('.medication-row').remove();return;}void execute(async()=>{if(el.dataset.trackBooking){trackedId=el.dataset.trackBooking;renderTracking();}
 if(el.dataset.chooseService){selectedService=el.dataset.chooseService;renderBrand();renderServices();await loadAvailability();showView('patient');$('#appointment-picker').scrollIntoView({behavior:'smooth',block:'start'});}
 if(el.dataset.date){selectedDate=el.dataset.date;await loadAvailability();}if(el.dataset.time){selectedTime=el.dataset.time;renderSlots();}
 if(el.dataset.tab)setTab(el.dataset.tab);
 if(el.dataset.staff)await staffAction(el.dataset.staff,el.dataset.id);if(el.dataset.editService)editService(el.dataset.editService);if(el.dataset.record)await openRecord(el.dataset.record);if(el.dataset.printVisit)printVisit(el.dataset.printVisit);
 switch(el.dataset.action){case 'patient':case 'admin':e.preventDefault();showView(el.dataset.action);break;case 'about':showView('patient');$('#about').scrollIntoView({behavior:'smooth'});break;case 'choose-slot':showView('patient');$('#appointment-picker').scrollIntoView({behavior:'smooth',block:'start'});$('#service-select').focus({preventScroll:true});break;case 'book':await openBooking();break;case 'support':window.open('https://wa.me/201551007018?text='+encodeURIComponent('مرحبًا، أحتاج طلب تعديل في '+clinic.name),'_blank','noopener,noreferrer');break;case 'workspace':selectWorkspace();break;case 'appointments':case 'payments':selectWorkspace(el.dataset.action);setTab(el.dataset.action);break;case 'all-dates':adminDate='';$('#admin-date').value='';if(live&&staff())await loadBookingHistory();render();break;case 'track':if(live&&api.session){await refresh();if(role==='patient')await loadBookingHistory();}syncTrackActions();$('#track-dialog').showModal();break;case 'track-last':$('#booking-dialog').close();if(live&&!api.session){$('#track-dialog').showModal();syncTrackActions();}else{if(live){await refresh();await loadBookingHistory();}renderTracking();$('#track-dialog').showModal();}break;case 'change-slot':$('#booking-dialog').close();showView('patient');break;case 'next':await staffAction('next');break;case 'pause':await staffAction(clinic.paused?'resume':'pause');break;case 'services':showServices();break;case 'new-service':editService(null);break;case 'settings':requireRole('doctor');for(const el of $('#settings-form').elements)if(el.name&&el.type!=='file')el.value=clinic[el.name]??'';updateDoctorPhotoPreview(clinic.photo_url);$('#settings-dialog').showModal();break;case 'records':await showRecords();break;case 'refresh-patients':requireRole('doctor');await loadPatients();notify(patients.length?'تم تحديث قائمة المرضى.':'لا توجد ملفات مرضى في العيادة الحالية.');break;case 'notifications':$('#notices').innerHTML=notifications.map(n=>`<p>${icon('bell')}${esc(n.message)}</p>`).join('')||'<p>لا توجد تنبيهات جديدة.</p>';$('#notice-dialog').showModal();break;case 'patient-login':if(live&&api.session){await api.logout();role='patient';bookings=[];historyBookings=[];historyLoaded=false;notifications=[];trackedId=null;}$('#track-dialog').close();$('#otp-dialog').showModal();break;case 'send-otp':{const phone=D.normalizePhone($('#otp-form').elements.phone.value);if(!/^01[0125]\d{8}$/.test(phone))throw Error('رقم الموبايل غير صالح.');await api.sendOTP(phone);notify('تم طلب رمز التحقق.');break;}case 'browser-notifications':if(!('Notification'in window))throw Error('المتصفح لا يدعم التنبيهات.');notify(await Notification.requestPermission()==='granted'?'تم التفعيل أثناء فتح الصفحة.':'لم يتم السماح بالتنبيهات.');break;case 'add-medication':addMedication();break;case 'logout':if(live)await api.logout();role='patient';selectWorkspace();if(live){bookings=[];historyBookings=[];historyLoaded=false;historyLoading=null;notifications=[];patients=[];}medical={};encounters=[];activeRecord=null;lastPrescription=null;trackedId=null;$('#print-area').innerHTML='';$('#extra-panel').innerHTML='';$('#extra-panel').hidden=true;$('#record-history').innerHTML='';$('#track-result').innerHTML='';showView('patient');break;
 }
});});
$('#service-select').addEventListener('change',e=>execute(async()=>{selectedService=e.target.value;renderBrand();renderServices();await loadAvailability();}));$('#form-service').addEventListener('change',e=>execute(async()=>{selectedService=e.target.value;renderBrand();renderServices();await loadAvailability();}));$('#booking-date').addEventListener('change',e=>execute(async()=>{selectedDate=e.target.value;await loadAvailability();}));$('#query').addEventListener('input',render);$('#booking-form').addEventListener('change',updateFee);
$('#booking-form').addEventListener('submit',e=>{e.preventDefault();execute(saveBooking);});
$('#track-form').addEventListener('submit',e=>{e.preventDefault();execute(async()=>{ensureDataMode();if(demo){renderTracking();return;}if(!api?.session){$('#track-dialog').close();$('#otp-dialog').showModal();return;}await refresh();if(role!=='patient')throw Error('اخرج من حساب الفريق ثم تحقق برقم الموبايل لمتابعة حجوزاتك.');await loadBookingHistory(true);trackedId=null;renderTracking();});});
$('#login-form').addEventListener('submit',e=>{e.preventDefault();execute(async()=>{const f=e.target.elements;await api.login(f.email.value,f.password.value);f.password.value='';await refresh();if(!staff()){await api.logout();throw Error('الحساب ليس عضوًا في فريق هذه العيادة.');}subscribe();$('#login-dialog').close();showView('admin');});});
$('#otp-form').addEventListener('submit',e=>{e.preventDefault();execute(async()=>{const f=e.target.elements;await api.verifyOTP(f.phone.value,f.token.value);f.token.value='';await refresh();subscribe();if(!staff())await loadBookingHistory();$('#otp-dialog').close();if($('#booking-form').elements.name.value){$('#booking-form').elements.phone.value=D.normalizePhone(f.phone.value);await openBooking();}else{syncTrackActions();$('#track-dialog').showModal();renderTracking();}});});
$('#demo-role')?.addEventListener('change',e=>{role=e.target.value;selectWorkspace();medical={};encounters=[];activeRecord=null;lastPrescription=null;$('#record-dialog').close();$('#print-area').innerHTML='';render();});
$('#settings-form').elements.photo_file.addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;execute(async()=>{ensureDataMode();requireRole('doctor');if(!live)throw Error('اربط Supabase قبل رفع الصور.');const url=await api.uploadClinicPhoto(clinic.id,file);$('#settings-form').elements.photo_url.value=url;updateDoctorPhotoPreview(url);notify('تم رفع الصورة. احفظ الإعدادات لتحديث صفحة العيادة.');});});$('#settings-form').elements.photo_url.addEventListener('input',e=>updateDoctorPhotoPreview(e.target.value));$('#settings-form').elements.template.addEventListener('change',e=>{const colors={classic:'#087f7b',ocean:'#2563eb',violet:'#7c3aed'};$('#settings-form').elements.accent.value=colors[e.target.value]||colors.classic;});
 $('#service-form').addEventListener('submit',e=>{e.preventDefault();execute(async()=>{ensureDataMode();requireRole('doctor');const f=e.target.elements,s=D.validateService({name:f.name.value.trim(),category:f.category.value,price:+f.price.value,duration_minutes:+f.duration_minutes.value,priority:+f.priority.value,active:f.active.value==='true'});if(live){await api.rpc('save_service',{p_clinic:clinic.id,p_service:editingService,p_data:s});await refresh();}else{if(editingService)services=services.map(x=>x.id===editingService?{...s,id:x.id}:x);else services.push({...s,id:crypto.randomUUID()});}if(!selected())selectedService=services.find(s=>s.active)?.id;$('#service-dialog').close();renderBrand();renderServices();await loadAvailability();showServices();notify('تم حفظ الخدمة.');});});
$('#settings-form').addEventListener('submit',e=>{e.preventDefault();execute(async()=>{ensureDataMode();requireRole('doctor');const data=Object.fromEntries(new FormData(e.target));delete data.photo_file;if(data.opens>=data.closes)throw Error('نهاية العمل لازم تكون بعد بدايته.');if(data.photo_url&&!/^https:\/\//.test(data.photo_url))throw Error('الصورة تحتاج رابط HTTPS.');if(/^https?:\/\//i.test(data.address)&&!D.isMapsLink(data.address))throw Error('الصق رابط Google Maps أو اكتب العنوان كنص.');if(live){await api.rpc('save_clinic',{p_clinic:clinic.id,p_data:data});await refresh();}else clinic={...clinic,...data,latitude:data.latitude===''?null:Number(data.latitude),longitude:data.longitude===''?null:Number(data.longitude),buffer_minutes:Number(data.buffer_minutes)};$('#settings-dialog').close();renderBrand();updateFee();await loadAvailability();notify('تم تحديث بيانات العيادة.');});});
$('#record-form').addEventListener('submit',e=>{e.preventDefault();execute(async()=>{ensureDataMode();requireRole('doctor');if(!activeRecord||!['inside','done'].includes(activeRecord.status))throw Error('ابدأ الكشف أولًا.');const f=e.target.elements,medications=[...$('#medications').children].map(r=>{const values=[...r.querySelectorAll('input')].map(i=>i.value.trim());if(values.some(v=>!v))throw Error('أكمل بيانات كل دواء.');return Object.fromEntries(['name','dose','frequency','duration'].map((k,i)=>[k,values[i]]));});const visit={id:crypto.randomUUID(),clinic_id:clinic.id,patient_id:activeRecord.patient_id,appointment_id:activeRecord.id,diagnosis:f.diagnosis.value.trim(),notes:f.notes.value,medications,created_at:new Date().toISOString()};if(live)visit.id=await api.rpc('save_encounter',{p_clinic:clinic.id,p_appointment:activeRecord.id,p_allergies:f.allergies.value,p_history:f.history.value,p_diagnosis:visit.diagnosis,p_notes:visit.notes,p_medications:medications});else{medical[activeRecord.patient_id]={allergies:f.allergies.value,history:f.history.value};encounters.unshift(visit);}lastPrescription=visit;notify('تم حفظ الكشف والروشتة.');await openRecord(activeRecord.id);});});
$('#admin-date').addEventListener('change',e=>execute(async()=>{adminDate=e.target.value;if(live&&staff()&&adminDate&&Date.parse(D.cairoInstant(adminDate,'23:59'))<Date.now()-30*86400000)await loadBookingHistory();render();}));$('#status-filter').addEventListener('change',e=>{stateFilter=e.target.value;render();});document.addEventListener('input',e=>{if(e.target.id==='patient-search')renderPatientDirectory(e.target.value);});
const notified=new Set();function checkReminders(){for(const b of bookings){if(b.id!==trackedId||!b.notification_consent||b.triage==='pending'||clinic.paused)continue;const eta=etaFor(b),kind=b.status==='inside'?'turn':b.status==='waiting'&&eta?.leaveIn===0?'leave':null,key=b.id+':'+kind;if(kind&&!notified.has(key)){notified.add(key);const message=kind==='turn'?'حان دورك. توجّه إلى الاستقبال.':'موعدك اقترب. راجع وقت الطريق وتحرك في الموعد المناسب.';notify(message);if('Notification'in window&&Notification.permission==='granted')new Notification(clinic.name,{body:message,tag:key});}}}
async function boot(){try{if(live){api=new ClinicAPI(config);api.consumeAuthRedirect();const data=await api.rpc('resolve_clinic',{p_host:location.hostname,p_slug:config.clinicSlug||query.get('clinic')||''});clinic=data.clinic;services=data.services;selectedService=services[0]?.id;$('.demo-strip').textContent='حجز ومتابعة مباشرة مع '+clinic.name;if(api.session){await refresh();subscribe();if(staff())showView('admin');}}renderBrand();renderServices();await loadAvailability();render();}catch(e){document.querySelectorAll('button').forEach(b=>b.disabled=true);$('.demo-strip').textContent=e.message==='العيادة غير متاحة حاليًا.'?'قاعدة Supabase متصلة. أضف بيانات العيادة وخدماتها وحساب الدكتور قبل تفعيل الحجز.':'تعذر فتح العيادة: '+e.message;}}
setInterval(()=>{if(live&&api?.session)refresh().then(checkReminders).catch(()=>{});else{if(trackedId)renderTracking();checkReminders();}},30000);
window.addEventListener('pagehide',()=>api?.disconnect());
document.querySelector('[role=tablist]').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const value=e.key==='Home'?'appointments':e.key==='End'?'payments':tab==='appointments'?'payments':'appointments';$('#tab-'+value).click();$('#tab-'+value).focus();}});
if(document.modelContext?.registerTool){try{const life=new AbortController();Promise.resolve(document.modelContext.registerTool({name:'start_clinic_booking',description:'Open the clinic booking form. Does not submit a booking.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async input=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw Error('Expected empty object');await openBooking();return{opened:true};}},{signal:life.signal})).catch(()=>{});window.addEventListener('pagehide',()=>life.abort());}catch{}}
void boot();

$('#existing-patient').addEventListener('change',e=>{const p=patients.find(p=>p.id===e.target.value);if(p){$('#booking-form').elements.name.value=p.name;$('#booking-form').elements.phone.value=p.phone;}});
